import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [meshUrl]
 * @property {Array<{name:string,params:any}>} [cinematicPrimitives]
 * @property {Array<any>} [textContent]
 * @property {Array<any>} [intent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} videoLoader
 * @property {any} fontAtlas
 * @property {Object<string,Function>} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;

  /** @type {import('three').Object3D} */
  const root = new Group();

  // Store resources to clean up later
  const _timelines = [];
  const _primitiveInstances = [];
  let _gltfScene = null;

  // Load GLB mesh (synchronous function, but loading is async)
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      _gltfScene = gltf.scene;
      root.add(_gltfScene);
    });
  }

  // Apply cinematic primitives if any
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const primitiveFn = ctx.primitives[prim.name];
      if (typeof primitiveFn === 'function') {
        const instance = primitiveFn(root, prim.params);
        if (instance) {
          _primitiveInstances.push(instance);
        }
      }
    }
  }

  // ---------- Interaction Handlers ----------
  /** Hover handler – rise‑in effect */
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(
    root.position,
    {
      y: '+=0.15',
      duration: 0.7,
      ease: 'power3.out',
    }
  );
  _timelines.push(hoverTimeline);

  root.userData.handlers = {};

  root.userData.handlers.hover = (payload) => {
    // Expect payload.type === 'enter' | 'leave'
    if (payload && payload.type === 'leave') {
      hoverTimeline.reverse();
    } else {
      hoverTimeline.play();
    }
  };

  /** Click handler – press‑down then emit navigation event */
  const clickHandler = () => {
    const clickTl = gsap.timeline({
      onComplete: () => {
        ctx.emit('hub-home.select');
      },
    });
    clickTl.to(
      root.scale,
      {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      }
    );
    _timelines.push(clickTl);
  };
  root.userData.handlers.click = clickHandler;

  // ---------- Cleanup ----------
  const disposeObject = (obj) => {
    if (obj.geometry) {
      obj.geometry.dispose();
    }
    if (obj.material) {
      if (Array.isArray(obj.material)) {
        obj.material.forEach((m) => m && m.dispose && m.dispose());
      } else {
        obj.material.dispose();
      }
    }
    if (obj.children) {
      obj.children.forEach(disposeObject);
    }
  };

  root.userData.cleanup = () => {
    // Kill GSAP timelines
    _timelines.forEach((tl) => tl.kill());

    // Cleanup primitives
    _primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    });

    // Dispose GLTF scene geometry/materials
    if (_gltfScene) {
      disposeObject(_gltfScene);
    }

    // Remove all children from root
    root.clear();
  };

  return root;
}
